import { describe, it } from "vitest";

// Reading adopted for premiums: every quote is a first insurance (+10 % of the
// policy base premium); follow-up contracts are later `quote` steps in the same
// scenario. Derived expected premiums show their arithmetic in the description.

describe("quote", () => {
  it.todo("empty item list -> premium 5 G (only the processing fee)");
  it.todo("plain sword, newcomer -> premium 115 G (100 + 10 first insurance + 5 fee)");
  it.todo("plain amulet, newcomer -> premium 71 G (60 + 6 + 5)");
  it.todo("plain staff, newcomer -> premium 93 G (80 + 8 + 5)");
  it.todo("plain potion, newcomer -> premium 49 G (40 + 4 + 5)");
  it.todo("1 rune, newcomer -> premium 33 G (25 + 2.5 + 5 = 32.5, rounded up in MHPCO's favor)");
  it.todo("1 moonstone, newcomer -> premium 33 G (25 + 2.5 + 5 = 32.5, rounded up)");
  it.todo("2 runes -> base 50 G -> premium 60 G (50 + 5 + 5)");
  it.todo("3 runes -> block base 60 G -> premium 71 G (60 + 6 + 5)");
  it.todo("4 runes -> no block, base 100 G -> premium 115 G");
  it.todo("7 runes -> base 175 G -> premium 198 G (175 + 17.5 + 5 = 197.5, rounded up)");
  it.todo("2 runes + 1 moonstone -> no block (different types), base 75 G -> premium 88 G (87.5 rounded up)");
  it.todo("3 moonstones -> block base 60 G -> premium 71 G");
  it.todo("3 runes + 3 moonstones -> two blocks, base 120 G -> premium 137 G (120 + 12 + 5)");
  it.todo("cursed sword (steel, enchantment 3), newcomer -> premium 165 G (100 + 50 curse + 10 + 5)");
  it.todo("cursed sword + plain amulet -> curse on the sword only: 160 + 50 + 16 first insurance + 5 -> premium 231 G");
  it.todo("sword with enchantment 4, not cursed -> no high-enchantment surcharge -> premium 115 G");
  it.todo("sword with exactly enchantment 5 -> high-enchantment surcharge -> premium 145 G (100 + 30 + 10 + 5)");
  it.todo("cursed sword with enchantment 5 -> both surcharges -> premium 195 G (100 + 50 + 30 + 10 + 5)");
  it.todo("customer with 1 year -> no loyalty discount; plain sword -> premium 115 G");
  it.todo("customer with exactly 2 years -> loyalty discount; plain sword -> premium 95 G (100 - 20 + 10 + 5)");
  it.todo("second quote of a newcomer -> follow-up discount; plain sword -> premium 100 G (100 + 10 - 15 + 5)");
  it.todo("third quote also receives the follow-up discount; plain sword -> premium 100 G");
  it.todo("long-standing customer's second contract, cursed sword enchantment 7, 3 years -> premium 160 G");
});

describe("claim", () => {
  it.todo("regular sword (steel, enchantment 3), damage 500 G -> payout 400 G, remaining cap 1600 G");
  it.todo("rune, damage 200 G -> payout 100 G, remaining cap 400 G (cap 2 x 250)");
  it.todo("sword and amulet, damage to amulet 200 G -> payout 100 G, remaining cap 3100 G (cap 3200)");
  it.todo("cursed sword, damage 500 G -> payout 400 G, remaining cap 1600 G (cap from unmodified value 1000)");
  it.todo("sword + 3 runes (block), damage to a rune 200 G -> payout 100 G, remaining cap 3400 G (sum 1750)");
  it.todo("dragon attack damages sword 500 G and amulet 300 G -> payout 600 G, remaining cap 2600 G (deductible per item)");
  it.todo("two swords, both damaged 500 G -> payout 800 G, remaining cap 3200 G (cap 4000, deductible per entry)");
  it.todo("steel sword, enchantment 9, damage 1000 G -> payout 400 G (50 % first, then deductible)");
  it.todo("dragon-material sword, exactly enchantment 8, damage 1000 G -> payout 400 G");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G -> payout 400 G (50 % rule wins)");
  it.todo("dragon-material sword, enchantment 5, damage 800 G -> payout 700 G (full reimbursement)");
  it.todo("steel sword, enchantment 9, damage 901 G -> payout 350 G (350.5 rounded down in MHPCO's favor)");
  it.todo("two successive claims of 1500 G on a sword -> payouts 1400 G / 600 G, remaining caps 600 G / 0 G");
  it.todo("schema example: 5-year customer, silver amulet enchantment 2 -> premium 59 G; fire damage 200 G -> payout 100 G, remaining cap 1100 G");
});

// Reading adopted for rejections: the CLI exits with status 1, writes an error
// description to stderr, and writes nothing to stdout.
describe("claim-office CLI", () => {
  it.todo("reads the schema example scenario from stdin and writes {results:[{premium:59},{payout:100,remainingCap:1100}]} to stdout");
  it.todo("quote with unknown item type 'broomstick' -> exit status 1, error on stderr, no stdout");
  it.todo("claim damaging an amulet when only a sword is insured -> exit status 1, error on stderr, no stdout");
  it.todo("claim damaging an unknown item type -> exit status 1, error on stderr, no stdout");
  it.todo("claim with damage amount -200 -> exit status 1, error on stderr, no stdout");
  it.todo("claim with two sword damages when only one sword is insured -> exit status 1, whole claim rejected, no stdout");
});

