import { quote, type Customer, type Item, type QuoteResult } from "./premium.js";

export type { Customer, Item, QuoteResult };

export interface Damage {
  itemType: string;
  amount: number;
}

export type Step =
  | { op: "quote"; items: Item[] }
  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export type StepResult = QuoteResult | ClaimResult;

export function runScenario(scenario: Scenario): { results: StepResult[] } {
  let contractsSoFar = 0;
  const results = scenario.steps.map((step) => {
    const result = quote(step.op === "quote" ? step.items : [], {
      customer: scenario.customer,
      isFollowUpContract: contractsSoFar > 0,
    });
    contractsSoFar++;
    return result;
  });
  return { results };
}

