p='src/claim.ts'
s=open(p).read()
s=s.replace('''function damagedItemOf(damage: Damage, policyItems: Item[]): Item {
  const damagedItem = policyItems.find((item) => item.type === damage.itemType);
  if (!damagedItem) throw new Error(`Damaged item '${damage.itemType}' is not insured by this policy`);
  return damagedItem;
}''','''/** Each damage entry refers to its own insured item; entries beyond the insured count of a type reject the claim. */
function damagedItemsOf(damages: Damage[], policyItems: Item[]): Item[] {
  const undamagedItems = [...policyItems];
  return damages.map((damage) => {
    const index = undamagedItems.findIndex((item) => item.type === damage.itemType);
    if (index < 0) throw new Error(`Damaged item '${damage.itemType}' is not insured by this policy (or not often enough)`);
    return undamagedItems.splice(index, 1)[0];
  });
}''')
s=s.replace('''  const unroundedPayout = damages.reduce((sum, damage) => sum + payoutOf(damage, damagedItemOf(damage, policy.items)), 0);''','''  const damagedItems = damagedItemsOf(damages, policy.items);
  const unroundedPayout = damages.reduce((sum, damage, i) => sum + payoutOf(damage, damagedItems[i]), 0);''')
open(p,'w').write(s)
EOF
